SELECT t2.overall_rating FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE SUBSTRING(t2."date", 1, 10) = '2016-02-04' AND t1.player_name = 'Aaron Mooy';

